-- Role pathways: which processes and IMS documents a position needs to know, from the Process Map.
-- ims_processes is reference data (read-only to the app). position_processes is curated by people managers.

create table if not exists public.ims_processes (
  code text primary key check (code ~ '^P[0-9]{3}$'),
  area text not null,
  title text not null,
  responsible_role text not null default '',
  approver_role text not null default '',
  read_docs text[] not null default '{}',
  fill_docs text[] not null default '{}'
);

create table if not exists public.position_processes (
  position_id uuid not null references public.positions(id) on delete cascade,
  process_code text not null references public.ims_processes(code) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (position_id, process_code)
);

on conflict (code) do update set area = excluded.area, title = excluded.title,
  responsible_role = excluded.responsible_role, approver_role = excluded.approver_role,
  read_docs = excluded.read_docs, fill_docs = excluded.fill_docs;

create or replace function public.admin_set_position_processes(p_actor uuid, p_position uuid, p_codes text[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_codes text[] := coalesce((select array_agg(distinct c) from unnest(p_codes) c), '{}');
begin
  perform public.app_require(p_actor, 'people.manage');
  if not exists (select 1 from public.positions where id = p_position) then
    raise exception 'Position not found.' using errcode = 'P0002';
  end if;
  if exists (select 1 from unnest(v_codes) c where not exists (select 1 from public.ims_processes where code = c)) then
    raise exception 'One or more processes do not exist.' using errcode = '22023';
  end if;
  delete from public.position_processes where position_id = p_position and process_code <> all (v_codes);
  select p_position, c from unnest(v_codes) c on conflict do nothing;
  perform public.ims_audit(p_actor, 'position_processes_set',
    jsonb_build_object('positionId', p_position, 'processes', to_jsonb(v_codes)));
end;
$$;

alter table public.ims_processes enable row level security;
alter table public.position_processes enable row level security;
revoke all on table public.ims_processes, public.position_processes from anon, authenticated;
grant select on table public.ims_processes, public.position_processes to service_role;
revoke execute on function public.admin_set_position_processes(uuid, uuid, text[]) from public, anon, authenticated;
grant execute on function public.admin_set_position_processes(uuid, uuid, text[]) to service_role;
